from .units import g_to_kg, half_even_div, kg_to_g

LIGHT_KG = "0.500"
MEDIUM_KG = "2.000"


def average_weight_kg(order):
    """Average weight of one unit in the order, rounded half to even; "0.000" when empty.

    >>> from shipcalc.models import Item, Order
    >>> average_weight_kg(Order([Item("A", "1.000"), Item("B", "2.000", 2)]))
    '1.667'
    """
    units = sum(item.qty for item in order.items)
    if units == 0:
        return "0.000"
    total = sum(kg_to_g(item.weight_kg) * item.qty for item in order.items)
    return g_to_kg(half_even_div(total, units))


def heaviest(order, n=3):
    return sorted(order.items, key=lambda item: (-kg_to_g(item.weight_kg), item.sku))[:n]


def weight_bands(order):
    bands = {"light": 0, "medium": 0, "heavy": 0}
    light, medium = kg_to_g(LIGHT_KG), kg_to_g(MEDIUM_KG)
    for item in order.items:
        grams = kg_to_g(item.weight_kg)
        if grams <= light:
            bands["light"] += item.qty
        elif grams <= medium:
            bands["medium"] += item.qty
        else:
            bands["heavy"] += item.qty
    return bands

