    return g_to_kg(abs(kg_to_g(declared_kg) - kg_to_g(measured_kg)))


def within_tolerance(declared_kg, measured_kg):
    """
    >>> within_tolerance("1.000", "1.020")
    True
    >>> within_tolerance("1.000", "1.021")
