"""Exports. The formats that other systems read stay in whole grams (docs/MIGRATION.md, "What stays in grams")."""
from .calc import order_weight_kg
from .packing import split_parcels
from .units import kg_to_g


def to_csv(order):
    lines = ["sku,weight_g,qty"]
    for item in order.items:
        lines.append(f"{item.sku},{kg_to_g(item.weight_kg)},{item.qty}")
    return "\n".join(lines) + "\n"


def _total_g(order):
    return kg_to_g(order_weight_kg(order))


def carrier_payload(order):
    return {"weight_g": _total_g(order), "parcels": len(split_parcels(order))}


def edi_segment(order):
    return f"WGT*G*{_total_g(order)}~"


def barcode(order):
    return f"WT{_total_g(order):010d}"

